// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address newOwner) public {
        // Keep the fuzzed domain wide: any address is admissible except the zero
        // address, which transferOwnership explicitly rejects by rule.
        vm.assume(newOwner != address(0));

        // The freshly deployed (uninitialized) contract's owner is address(0);
        // the current owner is thus address(0), so prank from it to satisfy
        // the onlyOwner modifier and drive the entry point transferOwnership.
        vm.prank(address(0));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever transferOwnership completes without reverting,
        // the contract's owner() must equal the requested newOwner.
        // Reference C always satisfies this; the mutant leaves owner() at
        // address(0), so the rule fails for any fuzzed newOwner != address(0).
        assertTrue(!ok || c.owner() == newOwner, "ownership transfer must update owner()");
    }
}
